const g = $input.first().json;
const e = g.estado_actual || {};
const u = g.umbrales || { co2:{limite:400}, sonido:{limite:80}, distancia:{limite:20} };

// El sistema evalua las condiciones de forma deterministica (no el LLM)
const alertas = [];
if (typeof e.co2 === 'number' && e.co2 > u.co2.limite) alertas.push("CO2 alto: " + e.co2 + " supera el umbral de " + u.co2.limite + " ppm");
if (typeof e.sonido === 'number' && e.sonido > u.sonido.limite) alertas.push("Sonido alto: " + e.sonido + " supera el umbral de " + u.sonido.limite + " dB");
if (typeof e.distancia === 'number' && e.distancia < u.distancia.limite) alertas.push("Distancia baja: " + e.distancia + " por debajo del umbral de " + u.distancia.limite + " cm");

const condiciones = alertas.length ? alertas.join("; ") : "NINGUNA - todos los valores estan dentro del rango seguro";

let prompt = "Eres un agente de control de un hogar inteligente. Herramientas disponibles:\n";
prompt += "- activar_actuador(dispositivo, estado)  // dispositivo: led o buzzer\n";
prompt += "- enviar_notificacion(mensaje)\n";
prompt += "- registrar_evento(descripcion)\n\n";
prompt += "Lecturas actuales de los sensores:\n";
prompt += "- CO2: " + e.co2 + " ppm (umbral critico: mayor a " + u.co2.limite + " ppm)\n";
prompt += "- Sonido: " + e.sonido + " dB (umbral critico: mayor a " + u.sonido.limite + " dB)\n";
prompt += "- Distancia: " + e.distancia + " cm (umbral critico: menor a " + u.distancia.limite + " cm)\n";
prompt += "- Persona detectada por camara: " + (e.persona ? "si" : "no") + "\n\n";
prompt += "CONDICIONES DE ALERTA YA EVALUADAS POR EL SISTEMA: " + condiciones + "\n\n";
prompt += "REGLAS OBLIGATORIAS:\n";
prompt += "1. Actua SOLO si en las condiciones ya evaluadas hay al menos una alerta real.\n";
prompt += "2. Si las condiciones dicen 'NINGUNA', tu respuesta DEBE ser exactamente: {\"acciones\":[],\"razonamiento\":\"Todos los valores dentro del rango seguro, no se requieren acciones.\"}\n";
prompt += "3. Prohibido inventar valores, condiciones o umbrales distintos a los indicados arriba.\n";
prompt += "4. El razonamiento debe citar solo las condiciones reales listadas arriba.\n\n";
prompt += "Responde SOLO en JSON con esta estructura:\n";
prompt += "{\"acciones\":[{\"herramienta\":\"activar_actuador\",\"parametros\":{\"dispositivo\":\"led\",\"estado\":true}}],\"razonamiento\":\"...\"}";

return [{ json: { model: 'llama3.2:3b', prompt: prompt, stream: false, format: 'json' } }];

const resp = $json.response || $json.data || '';
let decision;
try { decision = JSON.parse(resp); } catch(err) { decision = { acciones: [], razonamiento: 'error parse: ' + String(resp).slice(0,150) }; }
const acciones = decision.acciones || [];
const ejecutadas = [];
for (const acc of acciones) {
  const tool = acc.herramienta || acc.tool;
  const p = acc.parametros || acc.params || {};
  if (tool === 'activar_actuador') {
    try {
      await this.helpers.httpRequest({ method:'POST', url:'http://nodered:1880/agente/accion', body:{dispositivo:p.dispositivo, estado:p.estado}, json:true });
      ejecutadas.push('actuador ' + p.dispositivo + '=' + p.estado);
    } catch(err) { ejecutadas.push('error actuador: ' + err.message); }
  } else if (tool === 'enviar_notificacion') {
    ejecutadas.push('notif: ' + (p.mensaje||''));
  } else if (tool === 'registrar_evento') {
    ejecutadas.push('evento: ' + (p.descripcion||''));
  }
}
const raz = String(decision.razonamiento||'').replace(/"/g,"'").slice(0,200);
const accStr = (ejecutadas.join(' | ')||'ninguna').replace(/"/g,"'").slice(0,200);
const line = 'agente razonamiento="'+raz+'",acciones="'+accStr+'",num='+acciones.length;
try {
  await this.helpers.httpRequest({ method:'POST', url:'http://influxdb:8086/api/v2/write?org=smarthome&bucket=sensores&precision=s', headers:{'Authorization':'Token smarthome_token_2024','Content-Type':'text/plain'}, body: line });
} catch(err) {}
return [{ json: { razonamiento: decision.razonamiento, acciones_ejecutadas: ejecutadas, total: acciones.length } }];
